// The one carded action in the reference bridge: write a new file OUTSIDE the working
// directory, into a fixed folder the model cannot reach (docs/approval-card.md).
//
// Why this action: it passes test 4 of the approval card (the content is generated by the
// model), it reaches past the model's cage, and you can check the result with `ls`.
//
// The rules it follows (docs/identity.md, outbound):
//   - the target folder is fixed by config (BRIDGE_OUTSIDE_DIR), never chosen by the model;
//   - the file name is the draft id, a stable id made by the program, never a name the
//     model picked;
//   - check before write: same id and same content is "already done", same id and
//     different content is an error, never an overwrite;
//   - the write is exclusive and atomic (temp file, then a hard link that fails if the
//     target exists), so a crash leaves either no file or the whole file;
//   - read back after: success only when the bytes on disk hash to what was approved.
//
// An action module is a plain object: name, fields, describe, validate(), target(),
// current(), execute(). approval.mjs only ever calls those, so a second action (post into
// another chat, add a row to a table) is a second file with the same shape.

import {
  mkdirSync, realpathSync, lstatSync, readFileSync, writeFileSync, linkSync, unlinkSync,
} from 'node:fs';
import { createHash, randomBytes } from 'node:crypto';
import { isAbsolute, join, relative, sep } from 'node:path';

export const WRITE_OUTSIDE = 'write-outside';
export const FILE_EXTENSION = '.md';

// Every limit has a name. The content cap is set by the card, not by the disk: the card
// must show ALL of what will be written, so a draft too long to show is refused, never cut.
export const WRITE_OUTSIDE_LIMITS = {
  MAX_TITLE_CHARS: 120,
  MAX_CONTENT_CHARS: 3000,
};

// Draft ids are made by approval.mjs. Checked again here because this one becomes a filename.
export const DRAFT_ID_RE = /^draft-[a-z0-9]{6,12}-[0-9a-f]{8}$/;

// Characters that could make the card show something other than what is written:
// control characters (except newline and tab), bidirectional overrides, zero-width marks.
const HIDDEN_CHARS = /[\u0000-\u0008\u000B-\u001F\u007F-\u009F​-‏‪-‮⁠-⁤⁦-⁩﻿]/;

export const sha256 = (s) => createHash('sha256').update(s, 'utf8').digest('hex');

export function createWriteOutside({
  outsideDir = process.env.BRIDGE_OUTSIDE_DIR,
  workdir,
  limits = {},
} = {}) {
  const L = { ...WRITE_OUTSIDE_LIMITS, ...limits };
  if (!outsideDir || !isAbsolute(outsideDir)) {
    throw new Error('write-outside: BRIDGE_OUTSIDE_DIR must be set to an absolute path');
  }
  mkdirSync(outsideDir, { recursive: true });
  const dir = realpathSync(outsideDir);
  if (workdir) {
    // If one folder is inside the other, the model could write the "outside" file itself,
    // or read what the program wrote, and the card would guard nothing.
    const w = realpathSync(workdir);
    if (isInside(dir, w) || isInside(w, dir)) {
      throw new Error(`write-outside: ${dir} and the working directory ${w} overlap; pick a folder outside it`);
    }
  }

  return {
    name: WRITE_OUTSIDE,
    fields: ['title', 'content'],
    describe: 'Write a new file outside the working folder',
    dir,

    // Strict schema for the fields the model drafts. Returns the cleaned value or a
    // message a person can act on.
    validate(fields) {
      const { title, content } = fields || {};
      if (typeof title !== 'string') return fail('"title" must be a string (one line saying what this file is)');
      const t = title.trim();
      if (!t) return fail('"title" is empty');
      if (t.length > L.MAX_TITLE_CHARS) return fail(`"title" is ${t.length} characters; the limit is ${L.MAX_TITLE_CHARS}`);
      if (/[\r\n]/.test(t) || HIDDEN_CHARS.test(t)) return fail('"title" must be one line with no control or invisible characters');

      if (typeof content !== 'string') return fail('"content" must be a string (the exact text of the file)');
      const c = content.replace(/\r\n/g, '\n');
      if (!c.trim()) return fail('"content" is empty');
      if (c.length > L.MAX_CONTENT_CHARS) {
        return fail(`"content" is ${c.length} characters; the limit is ${L.MAX_CONTENT_CHARS}, because the card must show all of it`);
      }
      if (HIDDEN_CHARS.test(c)) {
        return fail('"content" contains control or invisible characters (for example a direction override or a zero-width space), so the card could not show exactly what would be written');
      }
      return { ok: true, value: { title: t, content: c } };
    },

    // The full path the program will write. Computed from the draft id, never from the draft.
    target(draftId) {
      if (!DRAFT_ID_RE.test(draftId)) throw new Error(`write-outside: bad draft id ${draftId}`);
      return join(dir, `${draftId}${FILE_EXTENSION}`);
    },

    // What is at the target now, for the card's "current" line.
    current(target) {
      const found = readExisting(target);
      if (!found) return { exists: false, text: 'no file at this path' };
      return { exists: true, text: `a file is already there (${found.length} characters); approving will NOT overwrite it` };
    },

    // Execute exactly the pinned draft. Throws on anything that is not a verified success.
    async execute({ id, target, content }) {
      const expected = this.target(id);
      if (target !== expected) throw new Error('target does not match the draft id; refusing');
      const want = sha256(content);

      for (let attempt = 0; attempt < 2; attempt++) {
        // 1. Check before write.
        const existing = readExisting(target);
        if (existing !== null) {
          if (sha256(existing) === want) return { status: 'already-done', path: target, sha256: want };
          throw new Error(`a different file already exists for this draft at ${target}; not overwritten. Check it by hand.`);
        }

        // 2. Write: temp file first, then a hard link, which fails if the target appeared
        //    in the meantime. Never an overwrite, never half a file at the target.
        const tmp = `${target}.tmp-${process.pid}-${randomBytes(4).toString('hex')}`;
        try {
          writeFileSync(tmp, content, { encoding: 'utf8', flag: 'wx' });
          try {
            linkSync(tmp, target);
          } catch (err) {
            if (err.code === 'EEXIST') continue;        // someone got there first: check again
            throw err;
          }
        } finally {
          try { unlinkSync(tmp); } catch {}
        }

        // 3. Read back. Exit 0 is not proof; the bytes on disk are.
        const back = readExisting(target);
        if (back === null) throw new Error(`wrote ${target} but could not read it back`);
        if (sha256(back) !== want) throw new Error(`read-back of ${target} does not match what was approved; check it by hand`);
        return { status: 'written', path: target, sha256: want };
      }
      throw new Error(`could not write ${target}: it kept changing under the write`);
    },
  };
}

// The file's text, or null if nothing is there. A symlink or a folder at the target is an
// error, not "nothing": something other than this action put it there.
function readExisting(target) {
  let st;
  try { st = lstatSync(target); } catch (err) {
    if (err.code === 'ENOENT') return null;
    throw err;
  }
  if (!st.isFile()) throw new Error(`${target} exists and is not a plain file; not touching it`);
  return readFileSync(target, 'utf8');
}

function isInside(child, parent) {
  const rel = relative(parent, child);
  return rel === '' || (rel !== '..' && !rel.startsWith(`..${sep}`) && !isAbsolute(rel));
}

function fail(error) { return { ok: false, error }; }
